use std::num::NonZeroU64;
pub fn parse_positive_pair(a: &str, b: &str) -> Result<u64, &'static str> {
    let x: u64 = a.parse().map_err(|_| "invalid_a")?;
    let y: u64 = b.parse().map_err(|_| "invalid_b")?;
    Ok(x + y)
}
