Cada acceso marca la entrada con un contador creciente y la expulsión busca la marca más baja. La búsqueda lineal cuesta O(n); una implementación de producción usaría una lista enlazada para obtener O(1), pero la versión simple es fácil de verificar.

```rust
use std::collections::HashMap;

struct Lru {
    capacity: usize,
    tick: u64,
    items: HashMap<String, (i32, u64)>,
}

impl Lru {
    fn new(capacity: usize) -> Lru {
        Lru { capacity, tick: 0, items: HashMap::new() }
    }

    fn get(&mut self, key: &str) -> Option<i32> {
        self.tick += 1;
        let tick = self.tick;
        self.items.get_mut(key).map(|entry| {
            entry.1 = tick;
            entry.0
        })
    }

    fn put(&mut self, key: &str, value: i32) {
        self.tick += 1;
        if !self.items.contains_key(key) && self.items.len() == self.capacity {
            if let Some(oldest) = self.items.iter().min_by_key(|(_, (_, used))| *used).map(|(k, _)| k.clone()) {
                self.items.remove(&oldest);
            }
        }
        if self.capacity > 0 {
            self.items.insert(key.to_string(), (value, self.tick));
        }
    }
}
```

