unsafe fn swap_raw(a: *mut i32, b: *mut i32) {
    let tmp = unsafe { *a };
    unsafe {
        *a = *b;
        *b = tmp;
    }
}

fn swap(a: &mut i32, b: &mut i32) {
    // SAFETY: dos referencias mutables son validas, estan alineadas y no se solapan.
    unsafe { swap_raw(a, b) }
}
```

